const rawOutput = $json.output;

if (!rawOutput) {
  throw new Error('AI Agent returned no output.');
}

let cleanedOutput = rawOutput.trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '');

try {
  const parsed = JSON.parse(cleanedOutput);

  return {
    json: {
      project_id: $('Sample Project Update').item.json.project_id,
      ...parsed,
    },
  };
} catch (error) {
  throw new Error(`Invalid JSON returned by AI Agent: ${error.message}`);
}

