  (() => {
    const probability = { Low: 1, Medium: 2, High: 3 }[$json.risks.probability] || 0;
    const impact = { Low: 1, Medium: 2, High: 3 }[$json.risks.impact] || 0;
    const score = probability * impact;

    if (score === 9) return 'Critical';
    if (score >= 6) return 'High';
    if (score >= 3) return 'Medium';
    return 'Low';
  })()
}}

